sys_ws_operation.operation_script:
(function process(request, response) {

    var number = request.queryParams.number;

    // Validate number
    if (!number) {
        response.setStatus(400);

        return {
            "status": "error",
            "message": "Please provide travel booking number"
        };
    }

    // Find travel booking
    var gr = new GlideRecord("x_2166443_info_t_0_travelbooking");
    gr.addQuery("number", number);
    gr.query();

    // Record not found
    if (!gr.next()) {
        response.setStatus(404);

        return {
            "status": "error",
            "message": "Travel booking not found: " + number
        };
    }

    // Successful response
    response.setStatus(200);

    return {
        "status": "success",
        "number": gr.getValue("number"),
        "caller": gr.getDisplayValue("caller"),
        "from": gr.getDisplayValue("from"),
        "destination": gr.getDisplayValue("destination"),
        "startdate": gr.getValue("startdate"),
        "return": gr.getValue("return"),
        "returndate": gr.getValue("returndate"),
        "travel_type": gr.getValue("travel_type"),
        "short_description": gr.getValue("short_description")
    };

})(request, response);
